interface Notifier { send(message: string): void }
class EmailNotifier implements Notifier { send(m: string){ console.log('email', m) } }
class SmsDecorator implements Notifier {
  constructor(private inner: Notifier){}
  send(m: string){ console.log('sms'); this.inner.send(m) }
}
const n = new SmsDecorator(new EmailNotifier())
n.send('hi')

interface Processor { process(amount: number): boolean }
class BaseProcessor implements Processor { process(a:number){ return true } }
class LoggingDecorator implements Processor {
  constructor(private inner: Processor){}
  process(a:number){ console.log('pay', a); return this.inner.process(a) }
}
class RetryDecorator implements Processor {
  constructor(private inner: Processor){}
  process(a:number){ /* retry logic */ return this.inner.process(a) }
}

// Version A
interface Renderer { render(text: string): string }
class PlainRenderer implements Renderer { render(t:string){ return t } }
class BoldDecorator implements Renderer {
  constructor(private inner: Renderer){}
  render(t:string){ return '<b>'+this.inner.render(t)+'</b>' }
}
class ItalicDecorator implements Renderer {
  constructor(private inner: Renderer){}
  render(t:string){ return '<i>'+this.inner.render(t)+'</i>' }
}
// Version B
class RichRenderer implements Renderer {
  constructor(private bold = false, private italic = false){}
  render(t:string){ let s = t; if(this.bold) s = '<b>'+s+'</b>'; if(this.italic) s = '<i>'+s+'</i>'; return s }
}
